CREATE TABLE scans (id INTEGER PRIMARY KEY, filename TEXT NOT NULL, created_at TEXT NOT NULL, risk_score INTEGER NOT NULL, risk_level TEXT NOT NULL, total_findings INTEGER NOT NULL, file_type TEXT NOT NULL DEFAULT 'TEXT', mime_type TEXT NOT NULL DEFAULT 'text/plain', analysis_method TEXT NOT NULL DEFAULT 'Text input', extraction_status TEXT NOT NULL DEFAULT 'Complete');
CREATE TABLE findings (id INTEGER PRIMARY KEY, scan_id INTEGER NOT NULL REFERENCES scans(id) ON DELETE CASCADE, type TEXT NOT NULL, severity TEXT NOT NULL, confidence REAL NOT NULL, masked_value TEXT NOT NULL, location TEXT NOT NULL);
